const ts=require(process.env.UI_TYPESCRIPT),fs=require('fs'),path=require('path');const dir='apps/web/src/components/ui';
for(const f of fs.readdirSync(dir).filter(x=>x.endsWith('.tsx')&&!x.includes('.test.'))){let s=fs.readFileSync(path.join(dir,f),'utf8');const source=ts.createSourceFile(f,s,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX),edits=[];
function visit(n){if(ts.isStringLiteral(n)&&n.text.includes(' ')&&/(^|\s)(bg-|flex\b|grid\b|text-|relative\b|inline-flex\b|absolute\b|fixed\b|border-)/.test(n.text)){const value=[...new Set(n.text.split(/\s+/))].join(' ');if(value!==n.text)edits.push({start:n.getStart(source),end:n.end,value:JSON.stringify(value)})}ts.forEachChild(n,visit)}visit(source);for(const e of edits.sort((a,b)=>b.start-a.start))s=s.slice(0,e.start)+e.value+s.slice(e.end);fs.writeFileSync(path.join(dir,f),s)}
